import json,sys,statistics,random
OUT=Path(__file__).resolve().parent;AP1=OUT.with_name('ap1-measurement');ROOT=OUT.parents[4];sys.path.insert(0,str(AP1));import run as r
r.OUT=OUT
reference=r.load(AP1/'ordinary-native-a.json')['representative_output_token_ids'];parent_arenas={mode:r.load(AP1/(mode+'-native-a.json'))['runs'][0]['engine_result'] for mode in ['ordinary','d2']}
identities={v:r.identity(OUT/('gem16-run-'+v)) for v in ['parent','candidate']}
assert 'ERROR SUMMARY: 0 errors' in (OUT/'d2-short-memcheck.sanitizer.log').read_text()
assert (OUT/'actual-production-dispatch.json').exists()

def ratio(a,b,seed):
 rng=random.Random(seed);samples=sorted(statistics.median(rng.choices(a,k=len(a)))/statistics.median(rng.choices(b,k=len(b)))-1 for _ in range(10000))
 return {'point':statistics.median(a)/statistics.median(b)-1,'bootstrap95':[samples[250],samples[9749]],'candidate_samples':a,'parent_samples':b}

def campaign(mode):
 samples={};cohorts={}
 for version,suffix in [('parent','a'),('candidate','b'),('candidate','b2'),('parent','a2')]:
  label=mode+'-'+version+'-'+suffix
  assert r.identity(OUT/('gem16-run-'+version))==identities[version]
  args=r.command(mode,label,native=True);args[args.index('--executable')+1]=str(OUT/('gem16-run-'+version))
  r.idle_and_cool();r.run(label,args,240,monitor=True)
  data=r.load(OUT/(label+'.json'));assert len(data['runs'])==10 and data['configuration']['warmups']==3
  for run in data['runs']:
   assert (run['prompt_tokens'],run['generated_tokens'],run['measured_decode_intervals'])==(16384,1135,1134)
   engine=run['engine_result'];assert engine['output_token_ids']==reference and not engine['fallbacks'] and not engine['token_loop_allocations']
   for key in ['weight_arena_bytes','workspace_bytes','kv_cache_bytes','precision','projection_path','routed_expert_path','decode_attention_path']:assert engine[key]==parent_arenas[mode][key],(label,key)
   if mode=='d2':assert (engine['mtp']['verification_groups'],engine['mtp']['proposed_tokens'],engine['mtp']['accepted_tokens'])==(502,1004,632)
  samples[suffix]=data['summary']['decode_tokens_per_second']['samples'];cohorts[label]=data
  print('COHORT',label,'median',statistics.median(samples[suffix]),flush=True)
 comparisons={'AB':ratio(samples['b'],samples['a'],2026110401),'BA':ratio(samples['b2'],samples['a2'],2026110402),'pooled':ratio(samples['b']+samples['b2'],samples['a']+samples['a2'],2026110403)}
 passed=all(v['bootstrap95'][0]>0 for k,v in comparisons.items() if k in ['AB','BA']) if mode=='d2' else all(v['point']>=0 and v['bootstrap95'][0]>-.002 for k,v in comparisons.items() if k in ['AB','BA'])
 result={'mode':mode,'identities':identities,'passed_predeclared_gate':passed,'comparisons':comparisons,'cohorts':cohorts,'scope':'unprofiled native candidate versus immediate qualified parent;Ordinaryboth95lower>0;D2eachpoint>=0and95lower>-.20%;all samples retained'}
 with (OUT/(mode+'-end-to-end.json')).open('x') as f:json.dump(result,f,indent=2)
 print('GATE',mode,passed,json.dumps(comparisons),flush=True)
 return passed

if not campaign('d2'):
